import React from 'react';
import {GestureDetector,Gesture,GestureHandlerRootView} from 'react-native-gesture-handler';
import Animated,{useSharedValue,useAnimatedStyle} from 'react-native-reanimated';
export default function D(){
  const x=useSharedValue(0);const y=useSharedValue(0);
  const g=Gesture.Pan().onChange(e=>{x.value+=e.changeX;y.value+=e.changeY;});
  const st=useAnimatedStyle(()=>({transform:[{translateX:x.value},{translateY:y.value}]}));
  return(<GestureHandlerRootView style={{flex:1}}><GestureDetector gesture={g}><Animated.View style={[{width:80,height:80,backgroundColor:'#0a84ff',borderRadius:12},st]}/></GestureDetector></GestureHandlerRootView>);}
